use super::*;
use crate::app::ChordSource;
use crest_tracker::chord_bank::ChordRevision;

pub(super) fn interval_label(intervals: &[i8]) -> String {
    const NAMES: [&str; 13] = [
        "1", "♭2", "2", "♭3", "3", "4", "♭5", "5", "♯5", "6", "♭7", "7", "8",
    ];
    intervals
        .iter()
        .map(|i| {
            usize::try_from(*i)
                .ok()
                .and_then(|i| NAMES.get(i))
                .map_or_else(|| format!("{i:+}"), |name| (*name).to_owned())
        })
        .collect::<Vec<_>>()
        .join(" – ")
}

/// Old autogenerated entries encoded the verification root into the label.
/// Display their quality without rewriting an immutable library revision.
pub(super) fn display_name(chord: &ChordRevision) -> String {
    let quality = chord.definition().shape().name();
    let legacy = chord.name().to_ascii_lowercase();
    if legacy
        .strip_prefix("chord")
        .or_else(|| legacy.strip_prefix("crd"))
        .map(str::trim)
        .is_some_and(|suffix| !suffix.is_empty() && suffix.chars().all(|c| c.is_ascii_digit()))
    {
        return quality;
    }
    for spelling in [
        crest_tracker::harmony::Spelling::Sharps,
        crest_tracker::harmony::Spelling::Flats,
    ] {
        if chord.name() == format!("{} {quality}", chord.verification().root().name(spelling)) {
            return quality;
        }
    }
    chord.name().into()
}

pub(crate) fn compact_name(chord: &ChordRevision) -> String {
    let name = display_name(chord);
    match name.as_str() {
        "Major" => "M",
        "Minor" => "m",
        "Diminished" => "dim",
        "Augmented" => "aug",
        "Sus2" => "sus2",
        "Sus4" => "sus4",
        "Major sixth" => "M6",
        "Minor sixth" => "m6",
        "Major seventh" => "M7",
        "Minor seventh" => "m7",
        "Dominant seventh" => "7",
        "Half-diminished" => "m7♭5",
        "Diminished seventh" => "dim7",
        _ => &name,
    }
    .into()
}

pub(super) fn choices(app: &App) -> Vec<(String, ChordSource, ChordRevision)> {
    let mut choices: Vec<_> = app
        .default_chords()
        .unwrap_or_default()
        .into_iter()
        .enumerate()
        .map(|(index, chord)| {
            (
                format!("chord:default:{index}"),
                ChordSource::Default { index },
                chord,
            )
        })
        .collect();
    if let Some(entries) = app.chord_library["entries"].as_array() {
        choices.extend(entries.iter().filter_map(|entry| {
            let digest = entry["digest"].as_str()?.to_owned();
            let chord = serde_json::from_value(entry["chord"].clone()).ok()?;
            Some((
                format!("chord:library:{digest}"),
                ChordSource::Library { digest },
                chord,
            ))
        }));
    }
    choices
}

pub(super) fn chord_rows(app: &App) -> Vec<WorkspaceRow> {
    let mut rows: Vec<_> = choices(app)
        .into_iter()
        .map(|(id, _, chord)| {
            row(
                id,
                display_name(&chord),
                interval_label(chord.definition().shape().intervals()),
            )
        })
        .collect();
    rows.push(row("chords_cancel", "Cancel", ""));
    rows
}

pub(super) fn chord_action(app: &mut App, id: &str) {
    if let Some((_, source, _)) = choices(app).into_iter().find(|(choice, _, _)| choice == id) {
        if chord_editor::apply(app, source) {
            open(app, None);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crest_tracker::{
        chord_bank::ChordDefinition,
        harmony::{Chord, ChordKind, Pitch},
    };
    #[test]
    fn grid_labels_use_quality_for_legacy_placeholders_and_preserve_custom_names() {
        let definition =
            ChordDefinition::new(Chord::from_kind(ChordKind::MajorSeventh), 0, false, 0).unwrap();
        for name in [
            "Chord 1",
            "chord2",
            "CRD00",
            "Major seventh",
            "C4 Major seventh",
        ] {
            let chord =
                ChordRevision::new(name.into(), definition.clone(), Pitch::new(60).unwrap())
                    .unwrap();
            assert_eq!(compact_name(&chord), "M7");
            assert_eq!(chord.name(), name);
        }
        let chord =
            ChordRevision::new("Wide chorus".into(), definition, Pitch::new(60).unwrap()).unwrap();
        assert_eq!(compact_name(&chord), "Wide chorus");
    }
}
